//! The editor tree's icons (`editor.explorer.icons`, #701), served to gpui
//! from the binary.
//!
//! Where it fits: `main.rs` registers `Assets` as the app's asset source, so a
//! `Resource::Embedded("explorer-icons/<icon>.svg")` loads through gpui's
//! `ImageAssetLoader`, which renders an SVG in its own colours (the Material
//! icons are many-coloured; `paint_svg` would tint them one colour).
//! `EditorBody::paint_tree` asks `resource` for the icon that
//! `infiniterm_core::explorer_icons::icon_for` picked. The bytes are in
//! `explorer_icon_svgs.rs`, generated by tools/explorer-icons.py.
//!
//! Embedded rather than read from the bundle so a joined window, a dev build
//! and a Linux build all have them without a path to find.
use crate::explorer_icon_svgs::SVGS;
use gpui::{AssetSource, Resource, Result, SharedString};
use std::borrow::Cow;

/// The prefix every icon's embedded path carries.
const PREFIX: &str = "explorer-icons/";

/// The app's asset source. Only the tree's icons live here; anything else
/// asked for is not found, as with gpui's default source.
pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> Result<Option<Cow<'static, [u8]>>> {
        Ok(svg(path).map(Cow::Borrowed))
    }

    fn list(&self, path: &str) -> Result<Vec<SharedString>> {
        Ok(SVGS
            .iter()
            .map(|(icon, _)| SharedString::from(format!("{PREFIX}{icon}.svg")))
            .filter(|p| p.starts_with(path))
            .collect())
    }
}

/// The embedded path of an icon `icon_for` named.
pub fn resource(icon: &str) -> Resource {
    Resource::Embedded(format!("{PREFIX}{icon}.svg").into())
}

fn svg(path: &str) -> Option<&'static [u8]> {
    let icon = path.strip_prefix(PREFIX)?.strip_suffix(".svg")?;
    let i = SVGS.binary_search_by(|(k, _)| (*k).cmp(icon)).ok()?;
    Some(SVGS[i].1)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_icon_core_can_name_is_embedded() {
        assert!(SVGS.windows(2).all(|w| w[0].0 < w[1].0));
        for (name, is_dir, open) in [
            ("main.rs", false, false),
            ("x.zzzunknown", false, false),
            ("src", true, false),
            ("src", true, true),
        ] {
            let icon = infiniterm_core::explorer_icons::icon_for(name, is_dir, open);
            assert!(svg(&format!("{PREFIX}{icon}.svg")).is_some(), "{icon}");
        }
        assert!(svg("explorer-icons/nope.svg").is_none());
        assert!(svg("rust.svg").is_none());
    }
}
